import math

def is_prime(n, primes):
    """Check if n is prime using trial division with precomputed primes."""
    if n < 2:
        return False
    for p in primes:
        if p * p > n:
            break
        if n % p == 0:
            return False
    return True

def solution(input_str):
    l, r = map(int, input_str.strip().split())

    answer = 0

    # Count the prime 2 if it's in range
    if l <= 2 <= r:
        answer += 1

    # We need to count odd primes p where p % 4 == 1
    # These are primes of the form 4k + 1
    # Start from first possible value (3, but adjusted to be >= l)
    start = max(l, 3)

    # We only need to check numbers that could be 1 mod 4
    # These are: 3 (3%4=3, skip), 5 (5%4=1, good), 9 (not prime), 13 (13%4=1, good), etc.
    # So we check values congruent to 1 mod 4, starting from 5
    for n in range(start if start % 4 == 1 else start + (1 - start % 4), r + 1, 4):
        if is_prime(n, primes):
            answer += 1

    return str(answer) + "\n"

