def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    permutation = list(map(int, lines[1].split()))

    # Find which positions are missing (have -1)
    missing_positions = []
    for i in range(n):
        if permutation[i] == -1:
            missing_positions.append(i + 1)  # 1-indexed positions

    # Find which values are missing
    used_values = set()
    for val in permutation:
        if val != -1:
            used_values.add(val)

    missing_values = set(range(1, n + 1)) - used_values

    k = len(missing_positions)  # Number of positions to fill
    r = 0  # Number of positions where position i is missing and value i is also missing

    for pos in missing_positions:
        if pos in missing_values:
            r += 1

    # Compute answer using inclusion-exclusion
    MOD = 1000000007

    # Precompute factorials
    factorials = [1] * (k + 1)
    for i in range(1, k + 1):
        factorials[i] = (factorials[i - 1] * i) % MOD

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        num = factorials[n]
        denom = (factorials[r] * factorials[n - r]) % MOD
        # Modular inverse using Fermat's little theorem
        denominator_inv = pow(denom, MOD - 2, MOD)
        return (num * denominator_inv) % MOD

    ans = 0
    for j in range(r + 1):
        ways = nCr(r, j) * factorials[k - j] % MOD
        if j % 2 == 0:
            ans = (ans + ways) % MOD
        else:
            ans = (ans - ways + MOD) % MOD

    return str(ans) + '\n'

