    _, diameter, dist_diameter = bfs(farthest_1)

    def bfs_path(start, end):
        q = deque([(start, 0)])
        visited = [False] * (n + 1)
        visited[start] = True

        while q:
            u, d = q.popleft()
            if u == end:
                return d
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    q.append((v, d + 1))
        return 0

    # Color using bipartition from BFS distances
    colors = [dist_diameter[i] % 2 for i in range(n + 1)]

    even_nodes = [i for i in range(1, n + 1) if colors[i] == 0]
    odd_nodes = [i for i in range(1, n + 1) if colors[i] == 1]

    assignment = [0] * (n + 1)

    if len(even_nodes) >= len(odd_nodes):
        # Match odd to even
        for i, odd_node in enumerate(odd_nodes):
            if i < len(even_nodes):
                assignment[odd_node] = even_nodes[i]
        # Remaining evens get matched to other evens (derangement within evens)
        for i in range(len(odd_nodes), len(even_nodes)):
            if i < len(even_nodes):
                idx = i % (len(even_nodes) - 1)
                assignment[even_nodes[i]] = even_nodes[idx]
            else:
                assignment[even_nodes[i]] = even_nodes[len(even_nodes)-1]
    else:
        # Match even to odd
        for i, even_node in enumerate(even_nodes):
            if i < len(odd_nodes):
                assignment[even_node] = odd_nodes[i]
        # Remaining odds get matched to other odds
        for i in range(len(even_nodes), len(odd_nodes)):
            if i < len(odd_nodes):
                idx = i % (len(odd_nodes) - 1)
                assignment[odd_nodes[i]] = odd_nodes[idx]

    # Build result permutation for villager 1..n
    result = [assignment[i] for i in range(1, n + 1)]
    assignment_str = " ".join(map(str, result))

    # Calculate total distance
    total = 0
    for i in range(1, n + 1):
        if result[i-1] != i:
            total += bfs_path(i, result[i-1])

    return f"{total}\n{assignment_str}\n"

