    def is_gp(seq):
        """Check if a sequence is a geometric progression."""
        if len(seq) <= 2:
            return True

        # All zeros is a GP
        if all(x == 0 for x in seq):
            return True

        # If first is zero, all must be zero
        if seq[0] == 0:
            return all(x == 0 for x in seq)

        # Check ratio consistency using cross-multiplication
        # For GP: ratio between consecutive elements is constant
        # i.e., seq[i]/seq[i-1] = seq[i-1]/seq[i-2]
        # Cross-multiplying: seq[i] * seq[i-2] = seq[i-1]²
        for i in range(2, len(seq)):
            if seq[i] * seq[i-2] != seq[i-1] ** 2:
                return False

        return True

    # Check if already a GP
    if is_gp(sequence):
        return "0\n"

    # Try removing each element
    for i in range(n):
        new_seq = sequence[:i] + sequence[i+1:]
        if is_gp(new_seq):
            return "1\n"

    return "2\n"

