    ref_x = sum(s[0] for s in ships) / n
    ref_y = sum(s[1] for s in ships) / n

    def get_angle(p, ref):
        return math.atan2(p[1] - ref[1], p[0] - ref[0])

    # Sort by angle from reference point
    ships_sorted = sorted(ships, key=lambda s: get_angle(s, (ref_x, ref_y)))
    bases_sorted = sorted(bases, key=lambda b: get_angle(b, (ref_x, ref_y)))

    # Build matching - ship index -> base index
    matching = {}
    for i in range(n):
        matching[ships_sorted[i][2]] = bases_sorted[i][2]

    # Build result array: result[i] = base index for ship i
