                max_edge[u][i] = max(max_edge[u][i - 1], max_edge[p][i - 1])
            else:
                parent[u][i] = 0

    def query_max_path(u, v):
        if u == v:
            return 0

        # Make u the deeper node
        if depth[u] < depth[v]:
            u, v = v, u

        ans = 0
        # Lift u to same depth as v
        for i in range(LOG - 1, -1, -1):
            if depth[u] - (1 << i) >= depth[v]:
                ans = max(ans, max_edge[u][i])
                u = parent[u][i]

        if u == v:
            return ans

        # Lift both u and v
        for i in range(LOG - 1, -1, -1):
            if parent[u][i] and parent[u][i] != parent[v][i]:
                ans = max(ans, max_edge[u][i], max_edge[v][i])
                u = parent[u][i]
                v = parent[v][i]

        # One more step to reach LCA
        ans = max(ans, max_edge[u][0], max_edge[v][0])
        return ans

