    # Memoization for leaf count and move number
    leaf_count_cache = {}
    move_num_cache = {}

    def get_leaf_count(node):
        if is_leaf[node]:
            return 1
        if node in leaf_count_cache:
            return leaf_count_cache[node]

        child0, child1 = children[node]
        lc = get_leaf_count(child0) + get_leaf_count(child1)
        leaf_count_cache[node] = lc
        return lc

    def get_move_number(node):
        """Move number when this node's combination happens"""
        if is_leaf[node]:
            return 0

        child0, child1 = children[node]
        m0 = get_move_number(child0)
        m1 = get_move_number(child1)

        move = max(m0, m1) + 1
        if node not in move_num_cache:
            move_num_cache[node] = move
        return move

    def compute_final_value(node, game_turns):
        """Compute the final value with knowledge of turn parity"""
        if is_leaf[node]:
