def build_transition(pattern: str) -> Tuple[int, List[List[int]]]:
    """Build KMP transition table: return (m, transitions) where transitions[state][char_code] = next_state"""
    m = len(pattern)
    lps = lps(pattern)
    trans = [[0] * 26 for _ in range(m + 1)]

