def find_last_disappearance(centers):
    n = len(centers)

    if n < 3:
        return -1

    distances = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            dx = centers[i][0] - centers[j][0]
            dy = centers[i][1] - centers[j][1]
            distances[i][j] = distances[j][i] = math.sqrt(dx * dx + dy * dy)

    max_inradius = 0.0

    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                a, b, c = distances[i][j], distances[j][k], distances[i][k]

                if a + b - c > 1e-9 and a + c - b > 1e-9 and b + c - a > 1e-9:
                    s = (a + b + c) / 2.0
                    area_sq = s * (s - a) * (s - b) * (s - c)
                    if area_sq > 1e-9:
                        area = math.sqrt(area_sq)
                        inradius = area / s

                        if inradius > max_inradius:
                            max_inradius = inradius

    return max_inradius

