    def bfs(start):
        dist = [-1] * (n + 1)
        dist[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)
        return dist

    # Precompute all-pairs distances
    dist = [bfs(i) for i in range(1, n + 1)]

    # Find 4 cities to maximize total distance
    max_total = -1
    best_order = []

    # Limit search space for efficiency
    limit = min(n, 500)

    for i in range(1, limit + 1):
        for j in range(i + 1, limit + 1):
            for k in range(j + 1, limit + 1):
                for l in range(k + 1, limit + 1):
                    # Check all possible orderings of these 4 cities
                    cities = [i, j, k, l]
                    from itertools import permutations

                    for perm in permutations(cities):
                        total = 0
                        valid = True
                        for t in range(3):
                            u = perm[t]
                            v = perm[t+1]
                            if dist[u][v] == -1:
                                valid = False
                                break
                            total += dist[u][v]

                        if valid and total > max_total:
                            max_total = total
                            best_order = list(perm)

    # Check remaining nodes if needed (higher numbers not covered by limit)
    if len(best_order) < 4:
        # Try including higher-numbered nodes
        for l in range(limit + 1, n + 1):
            for k in range(j + 1, limit + 1):
                for j_idx in range(i + 1, k):
                    cities = [i, j_idx, k, l]
                    # Try ordering with l as last
                    perm = (i, j_idx, k, l)
                    total = 0
                    valid = True
                    for t in range(3):
                        u = perm[t]
                        v = perm[t+1]
                        if dist[u][v] == -1:
                            valid = False
                            break
                        total += dist[u][v]

                    if valid and total > max_total:
                        max_total = total
                        best_order = list(perm)

    return ' '.join(map(str, best_order))

