def solution(input_text):
    lines = input_text.strip().split('\n')
    if not lines:
        return ""
    n, m = map(int, lines[0].split())

    # T orientations (relative to top-left corner, 3x3 bounding box)
    # Each shape has 5 cells
    orientations = [
        [(0,0), (0,1), (0,2), (1,1), (2,1)],  # Shape 1: top-heavy
        [(0,2), (1,0), (1,1), (1,2), (2,2)],  # Shape 2: right-heavy  
        [(0,1), (1,1), (2,0), (2,1), (2,2)],  # Shape 3: left-heavy
        [(0,1), (1,0), (1,1), (1,2), (2,2)],  # Shape 4: mixed
    ]

    best_count = 0
    best_grid = None

    def can_place(grid, r, c, shape):
        for dr, dc in shape:
            nr, nc = r + dr, c + dc
            if nr >= n or nc >= m or grid[nr][nc] != '.':
                return False
        return True

    def place(grid, r, c, shape, letter):
        for dr, dc in shape:
            grid[r + dr][c + dc] = letter

    def remove(grid, r, c, shape):
        for dr, dc in shape:
            grid[r + dr][c + dc] = '.'

    def backtrack(placed_count, grid):
        nonlocal best_count, best_grid
        remaining = n * m - sum(row.count('.') for row in grid)

        # Branch and bound: theoretical max with current + remaining cells
        if placed_count + (remaining + 4) // 5 <= best_count:
            return

        # Update best if we've placed a new maximum
        if placed_count > best_count:
            best_count = placed_count
            # Deep copy best grid
            best_grid = [row[:] for row in grid]

        # Try to place more pieces
        for r in range(n):
            for c in range(m):
                if grid[r][c] == '.':
                    # Try placing at this position with each orientation
                    for idx, shape in enumerate(orientations):
                        if can_place(grid, r, c, shape):
                            letter = chr(ord('A') + idx)
                            place(grid, r, c, shape, letter)
                            backtrack(placed_count + 1, grid)
                            remove(grid, r, c, shape)

    grid = [['.'] * m for _ in range(n)]
    backtrack(0, grid)

    return f"{best_count}\n" + "\n".join(["".join(row) for row in best_grid]) if best_grid else f"0\n" + "\n".join(["." * m] * n),

