def solution(input_str):
    """
    Solve the Appleman and Toastman game problem.

    Args:
        input_str: A string containing "n\nstring_t"

    Returns:
        A string with the answer as a single integer
    """
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    t = lines[1]

    # Calculate the maximum consecutive run for each character 'A', 'B', 'C', 'D'
    def max_run(s, char):
        max_r = 0
        cur = 0
        for c in s:
            if c == char:
                cur += 1
                max_r = max(max_r, cur)
            else:
                cur = 0
        return max_r

    # Run times for each character
    runs = []
    for c in 'ABCD':
        if c in t:
            runs.append(max_run(t, c))
        else:
            runs.append(0)  # Character doesn't exist in t

    # Find the minimum of the maximum run lengths
    k = min(runs)

    # If any character has run length 1, worst case is n
    # Otherwise worst case is ceil(n/2)
    if k == 1:
        return str(n)
    else:
        return str((n + 1) // 2)

