                for j in range(max(0, i - p[i]), i):
                    if not is_lit[j]:
                        direction[i] = 'L'
                        found = True
                        # Mark all reachable as illuminated
                        for k in range(max(0, i - p[i]), i):
                            if not is_lit[k]:
                                is_lit[k] = True
                        break

                if not found:
                    direction[i] = 'R'
                    # Mark all reachable to the right
                    for k in range(i + 1, min(n, i + p[i] + 1)):
                        if not is_lit[k]:
