def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return "NO\n"

    n, k = map(int, lines[0].split())
    s = lines[1]

    if len(s) != n:
        return "NO\n"

    offset = k
    # reachable[i][d] is True if diff = d - offset is reachable after i hands
    reachable = [[False] * (2 * k + 1) for _ in range(n + 1)]
    # choice[i][d] stores the character used to reach state (i, d-offset)
    choice = [[None] * (2 * k + 1) for _ in range(n + 1)]

    reachable[0][offset] = True

    for i in range(n):
        for diff in range(-k, k + 1):
            idx = diff + offset
            if not reachable[i][idx]:
                continue

            if s[i] == '?':
                chars = ['W', 'L', 'D']
            elif s[i] == 'W':
                chars = ['W']
            elif s[i] == 'L':
                chars = ['L']
            elif s[i] == 'D':
                chars = ['D']
            else:
                chars = []

            for c in chars:
                new_diff = diff
                if c == 'W':
                    new_diff += 1
                elif c == 'L':
                    new_diff -= 1
                # 'D' leaves diff unchanged

                if i == n - 1:
                    if abs(new_diff) == k:
                        reachable[i + 1][new_diff + offset] = True
                        choice[i + 1][new_diff + offset] = c
                else:
                    if abs(new_diff) < k:
                        reachable[i + 1][new_diff + offset] = True
                        choice[i + 1][new_diff + offset] = c

    final_diff = None
    for d in [k, -k]:
        if reachable[n][d + offset]:
            final_diff = d
            break

    if final_diff is None:
        return "NO\n"

    result = []
    current_diff = final_diff

    for i in range(n, 0, -1):
        c = choice[i][current_diff + offset]
        if c is None:
            return "NO\n"
        result.append(c)
        # Undo the change to get diff before this hand
        if c == 'W':
            current_diff -= 1
        elif c == 'L':
            current_diff += 1

    result.reverse()
    return ''.join(result) + '\n'

